CREATE TABLE worldchain.dex_pairs (`chain` String DEFAULT 'worldchain' CODEC(ZSTD(3)), `chainId` String DEFAULT '480' CODEC(ZSTD(3)), `pairAddress` String CODEC(ZSTD(3)), `dexId` String CODEC(ZSTD(3)), `url` String CODEC(ZSTD(3)), `baseToken_address` String CODEC(ZSTD(3)), `baseToken_name` String CODEC(ZSTD(3)), `baseToken_symbol` String CODEC(ZSTD(3)), `quoteToken_symbol` String CODEC(ZSTD(3)), `priceNative` Float64 CODEC(ZSTD(3)), `priceUsd` Float64 CODEC(ZSTD(3)), `fetch_type` Enum8('liquidity' = 1, 'hardcoded' = 2, 'api' = 3, 'manual' = 4) CODEC(ZSTD(3)), `timestamp` DateTime64(3) DEFAULT now64(3) CODEC(ZSTD(3)), `version` UInt64 CODEC(ZSTD(3))) ENGINE = ReplacingMergeTree(version) ORDER BY (chain, pairAddress) SETTINGS index_granularity = 8192;
CREATE TABLE worldchain.token_balances (`token_address` FixedString(42) CODEC(ZSTD(3)), `owner_address` String CODEC(ZSTD(3)), `balance_change` Int256 CODEC(ZSTD(3))) ENGINE = SummingMergeTree ORDER BY (token_address, owner_address) SETTINGS index_granularity = 8192;
CREATE TABLE worldchain.world_abi_signatures (`selector_or_topic` FixedString(32), `text_signature` String, `kind` LowCardinality(String), `source` LowCardinality(String), `updated_at` DateTime DEFAULT now()) ENGINE = MergeTree ORDER BY selector_or_topic SETTINGS index_granularity = 8192;
CREATE TABLE worldchain.world_address_labels (`chain_id` UInt32 DEFAULT 480, `address` FixedString(42), `label` String, `label_category` LowCardinality(String), `source` LowCardinality(String), `world_id_flag` UInt8 DEFAULT 0, `updated_at` DateTime DEFAULT now()) ENGINE = MergeTree ORDER BY (chain_id, address) SETTINGS index_granularity = 8192;
CREATE TABLE worldchain.world_blocks (`chain_id` UInt32 DEFAULT 480, `block_number` UInt64 CODEC(Delta(8), ZSTD(3)), `block_hash` FixedString(66) CODEC(ZSTD(3)), `parent_hash` FixedString(66) CODEC(ZSTD(3)), `timestamp` DateTime64(3) CODEC(DoubleDelta, ZSTD(3)), `miner` FixedString(42) CODEC(ZSTD(3)), `gas_limit` UInt64 CODEC(ZSTD(3)), `gas_used` UInt64 CODEC(ZSTD(3)), `base_fee_per_gas` UInt64 CODEC(Delta(8), ZSTD(3)), `transactions_count` UInt32 CODEC(ZSTD(3)), `size_bytes` UInt32 CODEC(ZSTD(3)), `ingested_at` DateTime64(3) DEFAULT now64(3), `is_canonical` UInt8 DEFAULT 1) ENGINE = MergeTree PARTITION BY toYYYYMM(timestamp) ORDER BY (chain_id, block_number) SETTINGS index_granularity = 8192;
CREATE TABLE worldchain.world_dex_trades (`chain_id` UInt32, `block_number` UInt64, `timestamp` DateTime, `tx_hash` FixedString(32), `log_index` UInt32, `pair_address` FixedString(20), `maker` FixedString(20), `token_in` FixedString(20), `token_out` FixedString(20), `amount_in` Float64, `amount_out` Float64, `price_native` Float64, `price_usd` Float64) ENGINE = MergeTree ORDER BY (pair_address, timestamp) SETTINGS index_granularity = 8192;
CREATE TABLE worldchain.world_logs (`chain_id` UInt32 DEFAULT 480, `block_number` UInt64 CODEC(Delta(8), ZSTD(3)), `block_hash` FixedString(66) CODEC(ZSTD(3)), `tx_index` UInt32 CODEC(ZSTD(3)), `tx_hash` FixedString(66) CODEC(ZSTD(3)), `log_index` UInt32 CODEC(Delta(8), ZSTD(3)), `address` FixedString(42) CODEC(ZSTD(3)), `topic0` FixedString(66) CODEC(ZSTD(3)), `topic1` FixedString(66) CODEC(ZSTD(3)), `topic2` FixedString(66) CODEC(ZSTD(3)), `topic3` FixedString(66) CODEC(ZSTD(3)), `data` String CODEC(ZSTD(3)), `removed` UInt8 DEFAULT 0, `ingested_at` DateTime64(3) DEFAULT now64(3), `is_canonical` UInt8 DEFAULT 1, INDEX idx_address address TYPE bloom_filter(0.01) GRANULARITY 4, INDEX idx_topic0 topic0 TYPE bloom_filter(0.01) GRANULARITY 4, INDEX idx_tx_hash tx_hash TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = MergeTree PARTITION BY toYYYYMM(ingested_at) ORDER BY (chain_id, block_number, tx_index, log_index) SETTINGS index_granularity = 8192;
CREATE TABLE worldchain.world_token_metadata (`chain_id` UInt32 DEFAULT 480, `contract_address` FixedString(42), `standard` LowCardinality(String), `symbol` String, `name` String, `decimals` UInt8, `first_seen_block` UInt64, `verified` UInt8 DEFAULT 0, `updated_at` DateTime DEFAULT now()) ENGINE = MergeTree ORDER BY (chain_id, contract_address) SETTINGS index_granularity = 8192;
CREATE TABLE worldchain.world_token_prices (`token_address` FixedString(42), `minute_bucket` DateTime, `price_usd` Float64, `liquidity_usd` Float64, `source_pair` FixedString(42)) ENGINE = ReplacingMergeTree ORDER BY (token_address, minute_bucket) SETTINGS index_granularity = 8192;
CREATE TABLE worldchain.world_traces (`chain_id` UInt32 DEFAULT 480, `block_number` UInt64 CODEC(Delta(8), ZSTD(3)), `block_hash` FixedString(66) CODEC(ZSTD(3)), `tx_index` UInt32 CODEC(ZSTD(3)), `tx_hash` FixedString(66) CODEC(ZSTD(3)), `trace_index` UInt32 CODEC(ZSTD(3)), `trace_address` Array(UInt32) CODEC(ZSTD(3)), `type` LowCardinality(String), `call_type` LowCardinality(String), `from_address` FixedString(42) CODEC(ZSTD(3)), `to_address` FixedString(42) CODEC(ZSTD(3)), `value_wei` UInt256 CODEC(ZSTD(3)), `gas` UInt64 CODEC(ZSTD(3)), `gas_used` UInt64 CODEC(ZSTD(3)), `input_data` String CODEC(ZSTD(3)), `output_data` String CODEC(ZSTD(3)), `revert_reason` String CODEC(ZSTD(3)), `status` UInt8 CODEC(ZSTD(3)), `ingested_at` DateTime64(3) DEFAULT now64(3), `is_canonical` UInt8 DEFAULT 1, INDEX idx_from from_address TYPE bloom_filter(0.01) GRANULARITY 4, INDEX idx_to to_address TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = MergeTree PARTITION BY toYYYYMM(ingested_at) ORDER BY (chain_id, block_number, tx_index, trace_index) SETTINGS index_granularity = 8192;
CREATE TABLE worldchain.world_transactions (`chain_id` UInt32 DEFAULT 480, `block_number` UInt64 CODEC(Delta(8), ZSTD(3)), `block_hash` FixedString(66) CODEC(ZSTD(3)), `tx_index` UInt32 CODEC(Delta(4), ZSTD(3)), `tx_hash` FixedString(66) CODEC(ZSTD(3)), `from_address` FixedString(42) CODEC(ZSTD(3)), `to_address` FixedString(42) CODEC(ZSTD(3)), `value_wei` UInt256 CODEC(ZSTD(3)), `gas_price_wei` UInt64 CODEC(ZSTD(3)), `max_fee_per_gas_wei` UInt64 CODEC(ZSTD(3)), `max_priority_fee_wei` UInt64 CODEC(ZSTD(3)), `gas_limit` UInt64 CODEC(ZSTD(3)), `gas_used` UInt64 CODEC(ZSTD(3)), `nonce` UInt64 CODEC(ZSTD(3)), `tx_type` UInt8 CODEC(ZSTD(3)), `input_data` String CODEC(ZSTD(3)), `status` UInt8 CODEC(ZSTD(3)), `effective_gas_price_wei` UInt64 CODEC(ZSTD(3)), `l1_fee_wei` UInt256 DEFAULT 0 CODEC(ZSTD(3)), `l1_gas_price_wei` UInt64 DEFAULT 0 CODEC(ZSTD(3)), `ingested_at` DateTime64(3) DEFAULT now64(3), `is_canonical` UInt8 DEFAULT 1, INDEX idx_from from_address TYPE bloom_filter(0.01) GRANULARITY 4, INDEX idx_to to_address TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = MergeTree PARTITION BY toYYYYMM(ingested_at) ORDER BY (chain_id, block_number, tx_index) SETTINGS index_granularity = 8192;

-- --------------------------------------------------------
-- 📊 TABLE: worldchain.world_token_transfers
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS worldchain.world_token_transfers (
    block_number UInt64 CODEC(Delta(8), ZSTD(3)),
    tx_hash FixedString(66) CODEC(ZSTD(3)),
    log_index UInt32 CODEC(ZSTD(3)),
    token_address FixedString(42) CODEC(ZSTD(3)),
    from_address FixedString(42) CODEC(ZSTD(3)),
    to_address FixedString(42) CODEC(ZSTD(3)),
    value String CODEC(ZSTD(3)),
    token_id String CODEC(ZSTD(3)),
    ingested_at DateTime64(3) DEFAULT now() CODEC(DoubleDelta, ZSTD(3))
) ENGINE = ReplacingMergeTree()
ORDER BY (block_number, tx_hash, log_index);
